(function(ctx){
var TOP=window.parent;var cfg=ctx.settings||{};
function reEsc(s){var out='',sp='\\^$*+?.()|{}[]';for(var i=0;i<s.length;i++){var c=s.charAt(i);out+=sp.indexOf(c)>=0?'\\'+c:c;}return out;}
function tagNames(){
  var out=[],seen={};
  String(cfg.tagsText||'options').split(/[\n,;]+/).forEach(function(line){
    var n=String(line||'').trim().replace(/^<\s*\/?/,'').replace(/\/?\s*>$/,'').replace(/\s+/g,'');
    if(n&&!seen[n]){seen[n]=1;out.push(n);}
  });
  return out;
}
function findBg(){
  try{
    var d=TOP.document;
    var b=d.getElementById('vnm-bg'); if(b) return b;
    var ifr=d.querySelectorAll('iframe');
    for(var i=0;i<ifr.length;i++){ try{ var id=ifr[i].contentDocument; if(id){ var bb=id.getElementById('vnm-bg'); if(bb) return bb; } }catch(e){} }
  }catch(e){}
  return null;
}
function findRaw(probe){
  try{
    var c=TOP.SillyTavern&&TOP.SillyTavern.getContext&&TOP.SillyTavern.getContext();
    var ch=c&&c.chat; if(!ch) return '';
    if(probe){
      for(var i=ch.length-1;i>=0;i--){
        var m=ch[i]; if(m.is_system) continue;
        var t=(m.mes||'').replace(/\s+/g,'');
        if(t&&t.indexOf(probe)>=0) return m.mes||'';
      }
    }
    for(var j=ch.length-1;j>=0;j--){ if(!ch[j].is_user&&!ch[j].is_system) return ch[j].mes||''; }
  }catch(e){}
  return '';
}
function extractBlocks(raw,tags){
  var out=[];
  for(var i=0;i<tags.length;i++){
    var re=new RegExp('<\\s*'+reEsc(tags[i])+'(?:\\s[^>]*)?>([\\s\\S]*?)<\\s*\\/\\s*'+reEsc(tags[i])+'\\s*>','gi');
    var m;
    while((m=re.exec(raw))!==null){
      out.push({tag:tags[i],content:m[1]});
      if(m[0]==='')re.lastIndex++;
    }
  }
  return out;
}
function parseOptions(content){
  var txt=String(content||'')
    .replace(/<summary[^>]*>[\s\S]*?<\/summary>/gi,'')
    .replace(/<br\s*\/?>/gi,'\n')
    .replace(/<[^>]+>/g,'');
  var lines=txt.split(/\n+/);
  var opts=[],seen={};
  for(var i=0;i<lines.length;i++){
    var t=lines[i].replace(/^\s+|\s+$/g,'');
    if(!t)continue;
    var m=/^【[^】]*】([\s\S]*)$/.exec(t);
    var label=m?m[1].replace(/^\s+|\s+$/g,''):t;
    if(!label||seen[label])continue;
    seen[label]=1;
    opts.push({full:t,label:label});
  }
  return opts;
}
function removePanel(){
  if(panelEl&&panelEl.parentNode)panelEl.parentNode.removeChild(panelEl);
  if(backdropEl&&backdropEl.parentNode)backdropEl.parentNode.removeChild(backdropEl);
  panelEl=null;backdropEl=null;
}
var dismissedSig='';
function dismiss(){ dismissedSig=lastSig; removePanel(); }
function renderPanel(ov,opts){
  removePanel();
  var doc=ov.ownerDocument;
  var ovRect=ov.getBoundingClientRect();
  var coverH=ov.clientHeight||ovRect.height||400;
  try{
    var dlg=ov.querySelector('#vnm-dialog')||ov.querySelector('.vnm-dialog');
    if(dlg){
      var dr=dlg.getBoundingClientRect();
      var dTop=dr.top-ovRect.top;
      if(dTop>0)coverH=Math.max(0,Math.min(coverH,dTop));
    }
  }catch(e){}
  backdropEl=doc.createElement('div');
  backdropEl.style.cssText='position:absolute;left:0;right:0;top:0;height:'+Math.round(coverH)+'px;background:rgba(0,0,0,.45);z-index:20;display:flex;align-items:center;justify-content:center;';
  backdropEl.addEventListener('click',function(e){ if(e.target===backdropEl){ dismiss(); } });
  panelEl=doc.createElement('div');
  panelEl.style.cssText='width:min(440px,86%);max-height:'+Math.max(200,Math.round(coverH-28))+'px;overflow-y:auto;background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.18);border-radius:22px;padding:18px 16px 14px;box-shadow:inset 0 1px 0 rgba(255,255,255,.28),inset 0 0 0 .5px rgba(255,255,255,.10),0 18px 60px rgba(0,0,0,.55);-webkit-backdrop-filter:blur(40px) saturate(170%) brightness(1.06);backdrop-filter:blur(40px) saturate(170%) brightness(1.06);';
  var hd=doc.createElement('div');
  hd.style.cssText='display:flex;align-items:center;justify-content:space-between;margin-bottom:10px;';
  var ht=doc.createElement('div');
  ht.textContent='行动选项';
  ht.style.cssText='font-size:16px;font-weight:700;color:rgba(255,255,255,.94);letter-spacing:.5px;';
  var xb=doc.createElement('div');
  xb.textContent='✕';
  xb.style.cssText='width:26px;height:26px;display:flex;align-items:center;justify-content:center;border-radius:9px;color:rgba(255,255,255,.5);cursor:pointer;font-size:14px;';
  xb.addEventListener('click',function(e){ e.stopPropagation(); dismiss(); });
  hd.appendChild(ht);hd.appendChild(xb);
  panelEl.appendChild(hd);
  opts.forEach(function(o){
    var btn=doc.createElement('div');
    var m=/^【[^】]*·([^】]*)】/.exec(o.full);
    var badge=m?('<span style="display:inline-block;padding:1px 7px;margin-right:7px;border-radius:8px;background:rgba(255,255,255,.14);font-size:10px;color:rgba(255,255,255,.8);vertical-align:1px;">'+String(m[1]).replace(/&/g,'&amp;').replace(/</g,'&lt;')+'</span>'):'';
    btn.innerHTML=badge+'<span style="color:rgba(255,255,255,.88);">'+String(o.label).replace(/&/g,'&amp;').replace(/</g,'&lt;')+'</span>';
    btn.style.cssText='padding:10px 12px;margin-bottom:8px;border:1px solid rgba(255,255,255,.14);border-radius:13px;background:rgba(255,255,255,.06);box-shadow:inset 0 1px 0 rgba(255,255,255,.16);font-size:13px;line-height:1.55;cursor:pointer;transition:background .15s,transform .08s;-webkit-backdrop-filter:blur(8px);backdrop-filter:blur(8px);';
    btn.addEventListener('mouseenter',function(){this.style.background='rgba(255,255,255,.13)';});
    btn.addEventListener('mouseleave',function(){this.style.background='rgba(255,255,255,.06)';});
    btn.addEventListener('click',function(e){
      e.stopPropagation();
      choose(o);
    });
    panelEl.appendChild(btn);
  });
  var tip=doc.createElement('div');
  tip.style.cssText='margin-top:4px;font-size:11px;color:rgba(255,255,255,.38);text-align:center;';
  tip.textContent=cfg.autoSend?'点击选项直接发送':'点击选项写入输入框,按 Enter 发送';
  panelEl.appendChild(tip);
  backdropEl.appendChild(panelEl);
  ov.appendChild(backdropEl);
}
function choose(o){
  var bg=findBg(); if(!bg||!bg.parentNode)return;
  var ov=bg.parentNode;
  var inp=ov.querySelector('#vnm-input');
  if(!inp)return;
  var val=cfg.sendWhat==='text'?o.label:o.full;
  inp.value=val;
  try{ inp.dispatchEvent(new (ov.ownerDocument.defaultView.Event||Event)('input',{bubbles:true})); }catch(e){}
  if(cfg.autoSend){
    try{
      var ev=new (ov.ownerDocument.defaultView.KeyboardEvent||ov.ownerDocument.defaultView.Event)('keydown',{key:'Enter',bubbles:true,cancelable:true});
      inp.dispatchEvent(ev);
    }catch(e){}
  }else{
    try{ inp.focus(); }catch(e){}
  }
  dismiss();
}
var panelEl=null,backdropEl=null,lastSig='';
function tick(){
  if(cfg.enabled===false){ if(TOP.__vnmChoicesTimer){TOP.clearInterval(TOP.__vnmChoicesTimer);TOP.__vnmChoicesTimer=null;} removePanel(); dismissedSig=''; return; }
  var bg=findBg();
  if(!bg||!bg.parentNode){ removePanel(); dismissedSig=''; return; }
  var ov=bg.parentNode;
  var st=null; try{ st=TOP.__vnmActiveState; }catch(e){}
  if(!st||!st.sentences||!st.sentences.length||st.idx!==st.sentences.length-1){ removePanel(); dismissedSig=''; return; }
  var te=ov.querySelector('#vnm-text');
  var cur=te?(te.textContent||''):'';
  var probe=cur?cur.replace(/\s+/g,'').slice(0,24):'';
  var raw=findRaw(probe);
  if(!raw){ removePanel(); dismissedSig=''; return; }
  var blocks=extractBlocks(raw,tagNames());
  var opts=[];
  for(var i=0;i<blocks.length;i++){ opts=opts.concat(parseOptions(blocks[i].content)); }
  if(!opts.length){ removePanel(); dismissedSig=''; return; }
  var sig=raw.length+':'+st.idx+':'+opts.length+':'+opts[0].full;
  if(sig!==lastSig){ lastSig=sig; dismissedSig=''; }
  if(sig===dismissedSig)return;
  if(sig===lastSig&&panelEl)return;
  renderPanel(ov,opts);
}
function install(){
  if(TOP.__vnmChoicesTimer)return;
  TOP.__vnmChoicesTimer=TOP.setInterval(function(){ try{ tick(); }catch(e){} },600);
}
install();
var root=ctx.div('','');
var card=ctx.div('v8card','');
card.style.cssText='margin:0 14px 14px;padding:14px 16px;';
card.innerHTML='<div style="font-size:14px;font-weight:600;color:rgba(255,255,255,.9);margin-bottom:8px;">行动选项捕获</div>'
  +'<div style="font-size:12px;line-height:1.8;color:rgba(255,255,255,.62);">'
  +'① 酒馆预设会在正文里输出形如 <span style="color:rgba(255,255,255,.85)">&lt;options&gt;…&lt;/options&gt;</span> 的选项块;<br>'
  +'② 在 设置 → 行动选项 里把预设的标签名加进"捕获标签"(每行一个);<br>'
  +'③ 阅读器里翻到本层<b>最后一段</b>时,自动弹出选项面板;<br>'
  +'④ 点击选项写入阅读器输入框(可在设置里改为直接发送);<br>'
  +'⑤ 选项块不会污染阅读器正文,聊天里的原始渲染也不受影响;<br>'
  +'⑥ 打开本页面即启动轮询(新版主正则下打开任意阅读器也会自动启动)。</div>';
root.appendChild(card);
return root;
})

